cd .v1 && npx tsx -e "
const { parse, stringify } = require('../src/index.ts');
const data = parse('/:test');
const TokenData = data.constructor;

// Check what the original stringified value is for é
const tokens = [
  { type: 'text', value: '/' },
  { type: 'param', name: 'test' },
  { type: 'text', value: 'é' },
];
console.log('ID test é:', /^[\$_\p{ID_Start}][\$\u200c\u200d\p{ID_Continue}]*$/u.test('test'));
console.log('ID_CONTINUE test é:', /^[\$\u200c\u200d\p{ID_Continue}]$/u.test('é'));
console.log('stringify:', stringify(new TokenData(tokens)));
"

