npx tsx -e '
import { parse, stringify, TokenData } from "./src/index.ts";

// Reproduce the exact bug: param followed by astral ID_Continue
const data = new TokenData([
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1D6FC}" },
]);
const result = stringify(data);
const expected = "/:\"test\"\u{1D6FC}";
console.log("Astral ID_Continue quoting:", result === expected ? "PASS ✅" : "FAIL ❌");

// Verify round-trip works
const reParsed = parse(result);
const reStringified = stringify(reParsed);
console.log("Round-trip:", reStringified === result ? "PASS ✅" : "FAIL ❌");

// Verify non-ID_Continue stays unquoted
const data2 = new TokenData([
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1F600}" },
]);
const result2 = stringify(data2);
console.log("Non-ID_Continue (emoji):", result2 === "/:test\u{1F600}" ? "PASS ✅" : "FAIL ❌");
'
